NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'II Corinthians'

CHAPTERS = {
    1: {
        1: 'Pavel, po Božji volji apostol Jezusa Kristusa, in naš brat Timótej Božji cerkvi, ki je v Korintu, z vsemi svetimi, ki so po vsej Ahaji:',
        2: '›Milost bodi vam in mir od Boga, našega Očeta in od Gospoda Jezusa Kristusa.‹',
        3: 'Blagoslovljen bodi Bog, celó Oče našega Gospoda Jezusa Kristusa, Oče usmiljenj in Bog vse tolažbe,',
        4: 'ki nas tolaži v vsaki naši stiski, da bomo sposobni tolažiti te, ki so v kakršnikoli težavi, s tolažbo, s katero smo mi sami potolaženi od Boga.',
        5: 'Kajti kakor so Kristusova trpljenja obilna v nas, tako je obilna tudi naša tolažba po Kristusu.',
        6: 'Če pa smo stiskani, je to za vašo tolažbo in rešitev duš, ki je učinkovita v prestajanju istih trpljenj, ki jih tudi mi prenašamo; ali če smo potolaženi, je to zaradi vaše tolažbe in rešitve duš.',
        7: 'In naše upanje o vas je neomajno, vedoč, da kakor ste udeleženci trpljenj, tako boste postali tudi tolažbe.',
        8: 'Kajti nočemo, bratje, da bi bili vi nevedni o naši težavi, ki je k nam prišla v Aziji, da smo bili stiskani preko mere, nad močjo, tako zelo, da smo obupali celó nad življenjem.',
        9: 'Toda v sebi smo imeli smrtno obsodbo, da ne bi zaupali vase, temveč v Boga, ki obuja mrtve;',
        10: 'ki nas je osvobodil iz tako velike smrti in še osvobaja; v katerega zaupamo, da nas bo še osvobajal.',
        11: 'Tudi vi skupaj pomagate z molitvijo za nas, da bi bila lahko zaradi daru, podarjenega nam, s pomočjo mnogih oseb, dana zahvala z naše strani.',
        12: 'Kajti naše veselje je to, pričevanje naše vesti, da smo se v svetu vedli s preprostostjo in pobožno iskrenostjo, ne z meseno modrostjo, temveč z Božjo milostjo in bolj obilno posebej do vas.',
        13: 'Kajti ne pišemo vam nobenih drugih stvari, kakor kar berete ali spoznavate; in zaupam, da boste spoznali celó do konca;',
        14: 'kakor ste nas tudi vi deloma spoznali, da smo mi vaše veselje, celó kakor ste tudi vi naše na dan Gospoda Jezusa.',
        15: 'V tem zaupanju sem bil voljan prej priti k vam, da bi vi lahko imeli dvojno korist;',
        16: 'in mimo vas iti v Makedonijo in iz Makedonije ponovno priti k vam in bi bil od vas pospremljen na svoji poti proti Judeji.',
        17: 'Ko sem bil torej takih misli, ali sem uporabil lahkomiselnost? Ali stvari, ki jih nameravam, nameravam storiti glede na meso, da bo z menoj »da,« »da« in »ne,« »ne«?',
        18: 'Toda kakor je Bog resničen, naša beseda do vas ni bila »da« in »ne.«',
        19: 'Kajti Božji Sin, Jezus Kristus, ki je bil med vami oznanjen po nas, celó po meni in Silvánu ter Timóteju, ni bil »da« in »ne,« temveč je bil v njem »da.«',
        20: 'Kajti vse Božje obljube so v njem »da« in v njem »Amen« v Božjo slavo po nas.',
        21: 'Torej tisti, ki nas z vami utrjuje v Kristusu in nas je mazilil, je Bog;',
        22: 'ki nas je tudi zapečatil in v naša srca dal poroštvo Duha.',
        23: 'Poleg tega kličem Boga za pričo nad svojo dušo, da doslej še nisem prišel k vam v Korint, da bi vam prizanesel.',
        24: 'Ne, ker bi imeli gospostvo nad vašo vero, temveč smo pomočniki vaše radosti; kajti stojite po veri.',
    },
    2: {
        1: 'Toda sam pri sebi sem sklenil, da k vam ne bom ponovno prišel s potrtostjo.',
        2: 'Kajti če vas užalostim, kdo je torej tisti, ki me razveseljuje, razen istega, ki je po meni užaloščen?',
        3: 'In to isto sem napisal vam, da ne bi, ko pridem, imel bridkost od teh, od katerih bi se moral veseliti; ker imam zaupanje v vas vse, da je moje veselje veselje vas vseh.',
        4: 'Kajti iz precejšnje stiske in tesnobe srca sem vam pisal z mnogimi solzami; ne da bi bili vi užaloščeni, temveč da bi lahko spoznali ljubezen, ki jo imam bolj obilno do vas.',
        5: 'Toda če je kdorkoli povzročil žalost, ni užalostil mene, temveč deloma, da vas ne bom vse preobremenil.',
        6: 'Takšnemu človeku je primerna ta kazen, katera [mu] je bila naložena od večine.',
        7: 'Tako da mu morate nasprotno vi raje odpustiti in ga potolažiti, da ne bi bil mogoče tak požrt s preveliko bridkostjo.',
        8: 'Zatorej vas rotim, da boste potrdili svojo ljubezen do njega.',
        9: 'Kajti zato sem vam tudi pisal, da bi lahko spoznal dokaz o vas, če ste v vseh stvareh poslušni.',
        10: 'Komur kaj odpustite, odpuščam tudi jaz. Kajti če sem kaj odpustil, komur sem zaradi vas to odpustil, sem to odpustil v Kristusovi osebi;',
        11: '§ da Satan ne bi pridobil prednosti pred nami; kajti o njegovih naklepih nismo nevedni.',
        12: 'Nadalje, ko sem prišel v Troádo, da oznanim Kristusov evangelij in so mi bila odprta vrata v Gospodu,',
        13: 'v svojem duhu nisem imel počitka, ker nisem našel svojega brata Tita. Toda ko sem se od njih poslovil, sem od tam odšel v Makedonijo.',
        14: 'Torej hvala bodi Bogu, ki nam vedno povzroča, da slavimo zmago v Kristusu in po nas na vsakem kraju razodeva vonj njegovega spoznanja.',
        15: 'Kajti Bogu smo prijeten Kristusov vonj med temi, ki so rešeni in med temi, ki se pogubljajo.',
        16: 'Nekomu smo vonj po smrti za smrt, drugemu pa vonj po življenju za življenje. In kdo je primeren za te stvari?',
        17: '§ Kajti nismo kakor mnogi, ki kvarijo Božjo besedo; temveč kot iz iskrenosti, vendar kot od Boga, v Božjih očeh govorimo v Kristusu.',
    },
    3: {
        1: 'Ali ponovno začenjamo priporočati sami sebe? Ali potrebujemo, kot nekateri drugi, za vas priporočilne poslanice ali priporočilna pisma od vas?',
        2: 'Vi ste naša poslanica, napisana v naših srcih, od vseh ljudi poznana in brana,',
        3: 'ker ste vidno oznanili, da ste Kristusova poslanica, dana po nas, ne napisana s črnilom, temveč z Duhom živega Boga; ne na kamnite plošče, temveč na mesene plošče srca.',
        4: 'In tako zaupanje imamo po Kristusu usmerjeno k Bogu;',
        5: 'ne da smo sami zadostni, da mislimo karkoli kakor od nas samih, temveč je naša zadostnost od Boga;',
        6: 'ki nas je tudi storil zmožne služabnike nove zaveze; ne po črki, temveč po duhu; kajti črka ubija, toda duh daje življenje.',
        7: 'Toda če je bilo veličastno služenje smrti, zapisano in vrezano v kamne, tako da Izraelovi otroci, zaradi slave njegove zunanjosti, niso mogli neomajno gledati Mojzesovega obraza, katerega slava je bila odpravljena,',
        8: 'kako ne bo služba duha precej veličastnejša?',
        9: 'Kajti če je služba obsodbi slava, [jo] služba pravičnosti veliko bolj prekaša v slavi.',
        10: 'Kajti celó to, kar je postalo slavno, v tem oziru ni imelo slave, zaradi slave, ki prekaša.',
        11: 'Kajti če je bilo slavno to, kar je bilo odpravljeno, je veliko bolj slavno to, kar ostaja.',
        12: 'Ker imamo torej tolikšno upanje, uporabljamo veliko razumljivost govora,',
        13: 'in ne kakor Mojzes, ki si je prek svojega obraza nadel zagrinjalo, da Izraelovi otroci niso mogli neomajno gledati konca tega, kar je odpravljeno.',
        14: 'Toda njihovi umi so bili zaslepljeni. Kajti do danes ostaja pri branju Stare zaveze isto zagrinjalo neodgrnjeno; katere zagrinjalo je odpravljeno v Kristusu.',
        15: 'Toda celó do današnjega dne, kadar se bere Mojzes, je na njihovem srcu zagrinjalo.',
        16: 'Pa vendar, ko se bodo obrnili h Gospodu, bo zagrinjalo odvzeto.',
        17: 'Torej Gospod je ta Duh, in kjer je Gospodov Duh, tam je svoboda.',
        18: 'Toda mi vsi, ki z odgrnjenim obrazom gledamo kakor v steklu Gospodovo slavo, smo iz slave v slavo preobraženi v isto podobo, celó kakor po Gospodovem Duhu.',
    },
    4: {
        1: 'Ker imamo to službo, kakor smo prejeli usmiljenje, ne omahujemo,',
        2: 'temveč smo se odrekli skritim stvarem nepoštenosti in ne hodimo v prebrisanosti niti z Božjo besedo ne ravnamo varljivo, temveč se z manifestacijo resnice v Božjih očeh priporočamo vesti vsakega človeka.',
        3: 'Toda če je naš evangelij skrit, je skrit tistim, ki so izgubljeni,',
        4: 'v katerih je bog tega sveta zaslepil misli tistih, ki ne verujejo, da jim ne bi zasijala svetloba veličastnega Kristusovega evangelija, ki je podoba Boga.',
        5: 'Kajti ne oznanjamo sebe, temveč Kristusa Jezusa, Gospoda; in sebe, vaše služabnike, zaradi Jezusa.',
        6: 'Kajti Bog, ki je zapovedal svetlobi, da zasije iz teme, je zasijal v naših srcih, da nudi svetlobo spoznanja Božje slave na obrazu Jezusa Kristusa.',
        7: 'Toda ta zaklad imamo v lončenih posodah, da bi bila odličnost moči lahko od Boga in ne od nas.',
        8: 'Na vsaki strani smo vznemirjeni, vendar ne v tegobi; zmedeni smo, vendar ne v obupu;',
        9: 'preganjani, toda ne zapuščeni; mêtani [ob tla], toda ne uničeni;',
        10: 'vedno v telesu naokrog prenašamo umiranje Gospoda Jezusa, da bi se lahko tudi v našem telesu razodelo Jezusovo življenje.',
        11: 'Kajti mi, ki živimo, smo zaradi Jezusa nenehno izročani v smrt, da bi se tudi Jezusovo življenje lahko razodelo v našem umrljivem mesu.',
        12: 'Tako potem v nas deluje smrt, toda v vas življenje.',
        13: 'Ker imamo istega duha vere, glede na to, kakor je pisano: ›Veroval sem in zato sem govoril;‹ tudi mi verujemo in zato govorimo;',
        14: 'vedoč, da tisti, ki je obudil Gospoda Jezusa, bo po Jezusu obudil tudi nas in nas postavil z vami.',
        15: 'Kajti vse stvari so zaradi vas, da bi lahko obilna milost zaradi zahvaljevanja mnogih prekipevala v Božjo slavo.',
        16: 'Zaradi tega razloga ne omagujemo; kajti kljub temu, da naš zunanji človek umira, je vendarle naš notranji človek iz dneva v dan obnovljen.',
        17: 'Kajti naša lahka stiska, ki je samo za trenutek, opravlja za nas veliko večjo, presegajočo in večno težo slave;',
        18: 'medtem ko ne gledamo na stvari, ki so vidne, temveč na stvari, ki so nevidne. Kajti stvari, ki so vidne, so začasne, toda stvari, ki so nevidne, so večne.',
    },
    5: {
        1: 'Kajti vemo, da če bi naša zemeljska hiša tega šotorskega svetišča razpadla, imamo v nebesih večno Božjo stavbo, hišo ne narejeno z rokami.',
        2: 'Kajti v tem stokamo in iskreno želimo, da bi se povrh odeli z našo hišo, ki je iz nebes;',
        3: '§ če je tako, da ko bomo oblečeni, ne bi bili najdeni goli.',
        4: 'Kajti mi, ki smo v tem šotoru, obteženi stokamo. Ne zato, ker hočemo biti neoblečeni, temveč oblečeni povrh, da bi bila umrljivost lahko požrta z življenjem.',
        5: 'Torej kdor nas je naredil za točno isto stvar, je Bog, ki nam je dal tudi poroštvo Duha.',
        6: 'Torej smo vedno zaupljivi, ker vemo, da medtem ko smo doma v telesu, smo odsotni od Gospoda',
        7: '(kajti hodimo po veri, ne po pogledu).',
        8: 'Zaupljivi smo, pravim in voljni rajši biti odsotni iz telesa in biti prisotni z Gospodom.',
        9: 'Zatorej se trudimo, da bomo bodisi prisotni ali odsotni, lahko pri njem sprejeti.',
        10: 'Kajti vsi se moramo prikazati pred Kristusovim sodnim stolom, da bo vsakdo lahko prejel stvari, storjene v svojem telesu, glede na to, kar je storil, bodisi je to dobro ali slabo.',
        11: 'Ker torej poznamo Gospodov strah, pregovarjamo ljudi; toda Bogu smo postali očitni; in zaupam tudi, [da] smo postali očitni v svojih vesteh.',
        12: 'Kajti ne priporočamo se vam ponovno, temveč vam dajemo priložnost, da ste zavoljo nas ponosni, da boste imeli nekaj, da odgovorite tem, ki se ponašajo na zunaj, ne pa v srcu.',
        13: 'Kajti če smo brez pameti, je to za Boga, ali če smo zdravega mišljenja, je to zaradi vaše stvari.',
        14: 'Kajti sili nas Kristusova ljubezen; ker tako sodimo, da če je eden umrl za vse, potem so bili mrtvi vsi.',
        15: 'In da je umrl za vse, da tisti, ki živijo, odslej ne bi živeli več zase, temveč za tistega, ki je zanje umrl in ponovno vstal.',
        16: 'Zatorej odslej nobenega človeka ne poznamo po mesu. Da, četudi smo Kristusa poznali po mesu, ga vendarle sedaj ne poznamo več [po mesu].',
        17: '§ Torej, če je katerikoli človek v Kristusu, je novo ustvarjeno bitje. Stare stvari so minile; glejte, vse stvari so postale nove.',
        18: 'In vse stvari so od Boga, ki nas je po Jezusu Kristusu spravil s seboj in nam dal službo pobotanja;',
        19: 'namreč, da je bil Bog v Kristusu, ko je svet pobotal s seboj, ker jim ni pripisal njihovih prekrškov, nam pa predal besedo sprave.',
        20: 'Torej smo potem predstavniki za Kristusa, kakor da vas je po nas rotil Bog. Namesto Kristusa vas prosimo, bodite spravljeni z Bogom.',
        21: 'Kajti njega, ki ni poznal greha, je zaradi nas storil, da postane greh, da bi mi lahko postali Božja pravičnost v njem.',
    },
    6: {
        1: 'Mi vas potem kot delavci skupaj z njim tudi rotimo, da Božje milosti niste prejeli zaman.',
        2: '(Kajti pravi: »Uslišal sem te v sprejemljivem času in na dan rešitve duše sem ti pomagal; glej, sedaj je odobren čas; glej, sedaj je dan rešitve duše.«)',
        3: 'Ne dajemo nobene spotike v nobeni stvari, da služba ne bo ošteta.',
        4: 'Toda v vseh stvareh se priporočamo kakor Božji služabniki, v veliki potrpežljivosti, v stiskah, v potrebah, v tegobah,',
        5: 'v bičanjih, v ječah, pri uporih, v naporih, v bedenjih, v postih,',
        6: 's čistostjo, s spoznanjem, s potrpežljivostjo, s prijaznostjo, s Svetim Duhom, z nehlinjeno ljubeznijo,',
        7: 'z besedo resnice, z Božjo močjo, z bojno opremo pravičnosti na desni roki in na levi,',
        8: 's spoštovanjem in nespoštovanjem, na slabem in dobrem glasu; kakor sleparji, pa vendar iskreni;',
        9: 'kakor neznani, pa vendar dobro znani; kakor umirajoči in glej, živimo; kakor kaznovani, pa ne ubiti;',
        10: 'kakor žalostni, vendar vedno veseli; kakor ubogi, vendar mnoge bogatimo; kakor ne bi imeli nič, pa vendar posedujemo vse stvari.',
        11: 'Oh vi Korinčani, naša usta so vam odprta, naše srce je širokosrčno.',
        12: 'Vi niste omejeni v nas, temveč ste omejeni v svojih lastnih notranjostih.',
        13: 'Torej za povračilo v enakem (govorim vam kakor svojim otrokom), bodite tudi vi širokosrčni.',
        14: 'Ne bodite neenako vpreženi skupaj z neverniki, kajti kakšno družbo ima pravičnost z nepravičnostjo? Ali kakšno udeležbo ima svetloba s temo?',
        15: 'In kakšno soglasje ima Kristus z Beliálom? Ali kakšen delež ima, kdor veruje, z neverniki?',
        16: '§ In kakšno strinjanje ima Božji tempelj z maliki? Kajti vi ste tempelj živega Boga; kakor je rekel Bog: »Prebival bom v njih in hodil v njih in jaz bom njihov Bog in oni bodo moji ljudje.',
        17: 'Zatorej pridite ven izmed njih in bodite oddvojeni,« govori Gospod »in nečiste stvari se ne dotikajte; in jaz vas bom sprejel',
        18: 'in vam bom Oče in vi boste moji sinovi in hčere,« govori Gospod Vsemogočni.',
    },
    7: {
        1: 'Ker imamo torej te obljube, srčno ljubljeni, se očistimo pred vso umazanijo mesa in duha ter v strahu Božjem dovršujmo svetost.',
        2: '§ Sprejmite nas; nikomur nismo storili krivice, nobenega človeka nismo pokvarili, nobenega človeka nismo ogoljufali.',
        3: 'Tega ne govorim, da vas obsodim, kajti prej sem rekel, da ste v naših srcih, da z vami umremo in živimo.',
        4: 'Velika je moja drznost govora do vas, veliko je moje ponašanje glede vas. Napolnjen sem s tolažbo, silno radosten v vsej naši stiski.',
        5: 'Kajti ko smo prišli v Makedonijo, naše meso ni imelo počitka, temveč smo bili stiskani na vsaki strani; zunaj so bili boji, znotraj so bili strahovi.',
        6: 'Kljub temu nas je Bog, ki tolaži te, ki so potrti, potolažil s Titovim prihodom;',
        7: 'pa ne samo z njegovim prihodom, temveč s tolažbo, s katero je bil potolažen med vami, ko nam je pripovedoval vašo iskreno željo, vaše žalovanje, vaše goreče mišljenje do mene; tako, da sem se tem bolj veselil.',
        8: 'Kajti čeprav sem vas s pismom užalostil, se ne kesam, čeprav sem se kesal; kajti zaznavam, da vas je ista poslanica užalostila, čeprav je bilo to samo za nekaj časa.',
        9: 'Sedaj se veselim, ne da ste bili užaloščeni, temveč da ste [bili] užaloščeni do kesanja. Kajti užaloščeni ste bili na bogaboječ način, da od nas v ničemer ne bi prejeli škode.',
        10: 'Kajti bogaboječa žalost opravlja kesanje v rešitev duše, ki se je ne bomo kesali, toda svetna žalost ustvarja smrt.',
        11: 'Kajti glejte to točno isto stvar, da ste bili užaloščeni na bogaboječ način, kakšno skrbnost je to storilo v vas, da, kakšno čiščenje vas samih, da, kakšno ogorčenost, da, kakšen strah, da, kakšno silovito hrepenenje, da, kakšno gorečnost, da, kakšno maščevanje! V vseh stvareh ste sebe potrdili, da ste v tej zadevi čisti.',
        12: 'Zatorej čeprav sem vam pisal, sem to storil ne zaradi razloga tistega, ki je storil krivico niti zaradi razloga tistega, ki je trpel krivico, temveč, da se vam lahko pokaže naša skrb za vas v Božjih očeh.',
        13: '§ Torej smo bili potolaženi v vaši tolažbi. Da in silno bolj smo se veselili zaradi Titovega veselja, ker je bil po vas vseh njegov duh okrepčan.',
        14: 'Kajti če sem se mu kakorkoli bahal z vami, nisem osramočen; temveč kakor smo vam govorili vse stvari v resnici, se je celó tako naše bahanje, ki sem ga storil pred Titom, izkazalo [za] resnično.',
        15: 'In njegova notranja strast je do vas obilnejša, medtem ko se spominja poslušnosti vas vseh, kako ste ga sprejeli s strahom in trepetanjem.',
        16: 'Veselim se torej, da imam v vas zaupanje v vseh stvareh.',
    },
    8: {
        1: 'Poleg tega, bratje, vam storimo, da veste o Božji milosti, podeljeni makedonskim cerkvam,',
        2: 'da je bila v veliki preizkušnji stiske obilica njihovega veselja in njihova globoka revščina obilna v bogastvih njihove velikodušnosti.',
        3: 'Kajti po svoji moči, pričujem, da in preko svojih moči so bili sami voljni',
        4: 'in [so] nas z mnogimi prošnjami prosili, da bi mi sprejeli dar in [oni] nase vzeli družbo služenja svetim.',
        5: 'In to so storili, ne kakor smo upali, temveč so najprej sebe izročili Gospodu in po Božji volji nam.',
        6: 'Tako, da smo prosili Tita, da kakor je začel, tako naj isto milost v vas tudi konča.',
        7: 'Torej kakor ste obilni v vsaki stvari, v veri, izgovarjavi, spoznanju, v vsej marljivosti in v vaši ljubezni do nas, glejte, da ste obilni tudi v tej milosti.',
        8: 'Ne govorim po zapovedi, temveč z razlogom gorečnosti drugih in da dokažem iskrenost vaše ljubezni.',
        9: 'Kajti poznate milost našega Gospoda Jezusa Kristusa, da čeprav je bil bogat, je vendar zaradi vas postal ubog, da bi po njegovi revščini vi lahko obogateli.',
        10: 'In v tem dajem svoj nasvet, kajti to je koristno za vas, ki ste prej začeli, ne samo delati, temveč ste bili prizadevni tudi pred enim letom.',
        11: 'Zdaj torej izvršite to delo; da kakor je bila pripravljenost hoteti, tako bo lahko tudi izvršitev iz tega, kar imate.',
        12: 'Kajti če je bil najprej voljan um, je sprejet glede na to, kar človek ima, in ne glede na to, česar nima.',
        13: 'Kajti ne mislim, da bi bili drugi ljudje olajšani, vi pa obteženi,',
        14: 'temveč prek enakosti, da lahko sedaj, ob tem času, vaše obilje postane oskrba za njihovo siromaštvo, da bo njihovo obilje lahko tudi oskrba za vaše siromaštvo, da bo lahko enakost,',
        15: 'kakor je pisano: ›Kdor je nabral veliko, ni imel ničesar preveč, in kdor je nabral malo, ni imel pomanjkanja.‹',
        16: 'Toda zahvala bodi Bogu, ki je na Titovo srce položil isto iskreno skrb za vas.',
        17: 'Kajti zares je sprejel spodbudo; toda ker je bil bolj prizadeven, je k vam odšel iz svojega lastnega nagiba.',
        18: 'In z njim smo poslali brata, katerega hvala v evangeliju je po vseh celotnih cerkvah;',
        19: 'in ne samo to, temveč ki je bil tudi od cerkvá izbran, da potuje z nami s to milostjo, ki je po nas preskrbljena v slavo istega Gospoda in izjavi vašega pripravljenega mišljenja;',
        20: 'izogibajoč se temu, da nas noben človek ne bi mogel oštevati v tem obilju, ki je preskrbljeno po nas;',
        21: 'ko skrbimo za poštene stvari, ne samo v Gospodovih očeh, temveč tudi v očeh ljudi.',
        22: 'In z njima smo poslali našega brata, ki se nam je pogosto v mnogih stvareh izkazal marljivega, toda sedaj mnogo bolj marljivega na veliko zaupanje, ki ga imam v vas.',
        23: 'Če kdorkoli poizveduje o Titu, je glede vas moj družabnik in sopomočnik, ali če bodo poizvedovali o [dveh] naših bratih, sta odposlanca cerkvá in Kristusova slava.',
        24: 'Zatorej pokažite njim in pred cerkvami dokaz svoje ljubezni in našega bahanja vam v prid.',
    },
    9: {
        1: 'Kajti glede služenja svetim, je zame odveč, da vam pišem,',
        2: 'kajti poznam pripravljenost vašega mišljenja, zaradi katerega se o vas baham tem iz Makedonije, da je bila Ahaja pripravljena pred enim letom; in vaša gorečnost je spodbudila zelo mnoge.',
        3: 'Vendar sem poslal brate, da ne bi bilo naše bahanje o vas, vam v prid, zaman; da boste, kakor sem rekel, vi lahko pripravljeni,',
        4: 'da ne bi bili morda, če pridejo z menoj tisti iz Makedonije in vas najdejo nepripravljene, mi (da ne rečem vi) osramočeni v tem istem zaupljivem bahanju.',
        5: 'Zatorej sem mislil, da je treba spodbuditi brate, da bi prej šli k vam in vnaprej pripravili vaš dar, o katerem ste prej imeli obvestilo, da bo isti lahko pripravljen kot resnična radodarnost in ne kakor od pohlepnosti.',
        6: 'Toda rečem to: »Kdor varčno seje, bo tudi varčno žel; in kdor radodarno seje, bo tudi radodarno žel.«',
        7: 'Vsak naj tako da, glede na to, kakor se je nameril v svojem srcu; ne nejevoljno ali iz nuje, kajti Bog ljubi vedrega darovalca.',
        8: 'In Bog je zmožen storiti, da bo vsa milost obilna do vas, da boste vedno imeli vso zadostnost v vseh stvareh [in boste] lahko bogati za vsako dobro delo',
        9: '(kakor je pisano: ›Razdelil je povsod, dal je revnim. Njegova pravičnost ostaja na veke.‹',
        10: 'Torej kdor daje seme sejalcu, daje tako kruh za vašo hrano, kakor množi vaše posejano seme in povečuje sadove vaše pravičnosti)',
        11: 'obogateli ste v vsaki stvari za vso radodarnost, ki po nas povzroča zahvaljevanje k Bogu.',
        12: 'Kajti služenje tej službi ni samo oskrba potreb svetih, temveč je po mnogih zahvaljevanjih tudi obilna Bogu;',
        13: 'čeprav s poskusom tega služenja proslavljajo Boga zaradi vaše izražene podložnosti Kristusovemu evangeliju in zaradi vaše velikodušne razdelitve njim in vsem ljudem;',
        14: 'in z njihovo molitvijo za vas, kateri zaradi silne Božje milost v vas hrepenijo po vas.',
        15: 'Hvala bodi Bogu za njegov neizrekljivi dar.',
    },
    10: {
        1: 'Torej jaz sam, Pavel, ki sem v navzočnosti med vami pohleven, toda odsoten sem drzen do vas, vas pri Kristusovi krotkosti in blagosti rotim.',
        2: 'Toda rotim vas, da ne bi bil drzen, ko sem prisoten s tem zaupanjem, s katerim mislim biti do nekaterih drzen, ki mislijo o nas, kakor da smo živeli glede na meso.',
        3: 'Kajti čeprav živimo v mesu, se ne borimo po mesu',
        4: '(kajti orožja našega vojskovanja niso mesena, temveč mogočna po Bogu, da podirajo trdnjave);',
        5: 'podiramo zamisli in vsako visoko stvar, ki sebe povzdiguje proti spoznanju Boga ter vsako misel prinašamo v ujetništvo, v poslušnost Kristusu;',
        6: 'in v pripravljenosti smo, da maščujemo vso neposlušnost, ko se vaša poslušnost dopolni.',
        7: 'Ali gledate na stvari po zunanjem videzu? Če katerikoli človek zaupa sebi, da je Kristusov, naj sam v sebi to ponovno razmisli, da kakor je on Kristusov, točno tako smo mi Kristusovi.',
        8: '§ Kajti čeprav bi se malce bolj bahal z našo oblastjo, ki nam jo je Gospod dal za izgrajevanje in ne za vaše uničenje, ne bi bil osramočen;',
        9: 'da ne bom videti, kakor če vas hočem strašiti s pismi.',
        10: 'Kajti [za] njegova pisma, pravijo, [da] so tehtna in vplivna, toda njegova telesna prisotnost je šibka in njegov govor zaničevanja vreden.',
        11: 'Naj takšni mislijo to, da takšni, kakor smo mi z besedo po črkah, ko smo odsotni, bomo takšni tudi v dejanju, ko smo prisotni.',
        12: 'Kajti ne drznemo se meriti ali primerjati z nekaterimi, ki priporočajo sami sebe. Toda tisti, ki sebe merijo s seboj in se primerjajo med seboj, niso modri.',
        13: 'Toda mi se ne bomo bahali o stvareh zunaj naše mere, temveč glede na mero oblasti, ki nam jo je Bog razdelil, mero, da smo segli celó do vas.',
        14: 'Kajti ne iztezamo se preko naše mere, kakor da nismo prispeli do vas, kajti z oznanjevanjem Kristusovega evangelija smo prišli tudi prav do vas.',
        15: 'O stvareh se ne bahamo prek naše mere, to je z napori drugih ljudi, temveč imamo upanje, ko se vaša vera okrepi, da bomo obilno povečani po vas glede na naše območje,',
        16: 'da oznanimo evangelij v pokrajinah onstran vas in ne da se bahamo na področju drugega človeka o stvareh, ki so bile pripravljene k naši roki.',
        17: 'Toda kdor se ponaša, naj se ponaša v Gospodu.',
        18: 'Kajti ni potrjen kdor priporoča sebe, temveč kogar priporoča Gospod.',
    },
    11: {
        1: 'Bog daj, da bi lahko z menoj malo zdržali v moji neumnosti, in zares potrpite z menoj.',
        2: 'Kajti nad vami sem ljubosumen z bogaboječo ljubosumnostjo, kajti zaročil sem vas z enim soprogom, da vas lahko kakor čiste device predstavim Kristusu.',
        3: 'Toda bojim se, da ne bi bila na kakršenkoli način, kakor je kača s svojo premetenostjo preslepila Evo, tudi vaša mišljenja pokvarjena proč od preprostosti, ki je v Kristusu.',
        4: 'Kajti če tisti, ki prihaja, oznanja drugega Jezusa, ki ga nismo oznanili ali če sprejmete drugega duha, ki ga niste prejeli ali drug evangelij, ki ga niste sprejeli, bi bili mogoče z njim prizanesljivi.',
        5: 'Kajti domnevam, da nisem bil niti malo za zelo vodilnimi apostoli.',
        6: 'Toda čeprav sem grob v govoru, pa nisem v spoznanju; toda med vami smo se temeljito razodeli v vseh stvareh.',
        7: 'Ali sem zagrešil prestopek s poniževanjem samega sebe, da bi bili vi lahko povišani, ker sem vam brez plačila oznanil Božji evangelij?',
        8: 'Odvzel sem drugim cerkvam in od njih jemal plačila, da vam storim uslugo.',
        9: 'In ko sem bil prisoten z vami in trpel pomanjkanje, nisem bil v breme nobenemu človeku, kajti to, kar mi je primanjkovalo, so preskrbeli bratje, ki so prišli iz Makedonije. In v vseh stvareh sem se varoval pred tem, da bi vam bil v breme in tako se bom varoval.',
        10: 'Kakor je Kristusova resnica v meni, me v področjih Ahaje noben človek ne bo ustavil v tem bahanju.',
        11: 'Zakaj? Ker vas ne ljubim? Bog ve.',
        12: 'Toda kar delam, to bom delal, da bom lahko odsekal priložnost pred temi, ki želijo priložnost; da bodo, v čemer se ponašajo, lahko najdeni kakor mi.',
        13: 'Kajti takšni so lažni apostoli, varljivi delavci, ki se prenarejajo v Kristusove apostole.',
        14: 'In nič čudnega; kajti sam Satan se prenareja v angela svetlobe.',
        15: 'Torej ni nič posebnega, če so tudi njegovi služabniki prenarejeni kakor služabniki pravičnosti, katerih konec bo glede na njihova dela.',
        16: 'Ponovno pravim: ›Naj me noben človek nima za bedaka; če drugače, me vendar sprejmite kakor bedaka, da se bom lahko malce bahal.',
        17: 'To, kar govorim, tega ne govorim po Gospodu, temveč kakor bi bilo nespametno v tem zaupanju bahanja.',
        18: 'Ker pa se mnogi ponašajo po mesu, se bom tudi jaz ponašal.',
        19: 'Kajti z veseljem trpite bedake, ker ste vi sami modri.',
        20: 'Kajti trpite, če vas človek privleče v suženjstvo, če vas človek požira, če od vas človek jemlje, če človek sebe povišuje, če vas človek udari po obrazu.',
        21: 'Govorim glede graje, kakor bi bili šibki. Čeprav v čemer je kdorkoli drzen (govorim nespametno), sem tudi sam drzen.',
        22: 'Ali so Hebrejci? Tudi jaz sem. Ali so Izraelci? Tudi jaz sem. Ali so Abrahamovo seme? Tudi jaz sem.',
        23: 'Ali so Kristusovi služabniki? (Govorim kakor bedak.) Jaz sem bolj; obilnejši v naporih, nad mero pri bičanjih, pogosteje v ječah, često v smrtnih nevarnostih.',
        24: 'Od Judov sem petkrat prejel štirideset udarcev z bičem, izvzemši enega.',
        25: 'Trikrat sem bil pretepen s šibami, enkrat sem bil kamnan, trikrat sem pretrpel brodolom, noč in dan sem bil na globokem morju;',
        26: 'pogosto na potovanjih, v nevarnostih od vodá, v nevarnostih od roparjev, v nevarnostih od svojih lastnih rojakov, v nevarnostih od poganov, v nevarnostih v mestu, v nevarnostih v divjini, v nevarnostih na morju, v nevarnostih med lažnivimi brati;',
        27: 'v utrujenostih in bolestih, v pogostih bedenjih, v lakoti in žeji, v pogostih postih, v mrazu in nagoti.',
        28: 'Poleg teh stvari, ki so zunanje, to, kar dnevno prihaja nadme, [še] skrb za vse cerkve.',
        29: 'Kdo je slaboten in jaz nisem slaboten? Kdo je užaljen in jaz ne gorim?',
        30: 'Če se moram nujno ponašati, se bom ponašal s stvarmi, ki se tičejo mojih slabotnosti.',
        31: 'Bog in Oče našega Gospoda Jezusa Kristusa, ki je blagoslovljen na vékomaj, ve, da ne lažem.',
        32: 'V Damasku je voditelj pod kraljem Arétom z garnizijo zastražil mesto Damaščanov, željan, da me zgrabi,',
        33: 'pa sem bil skozi okno v košu spuščen dol ob zidu in pobegnil njegovim rokam.‹',
    },
    12: {
        1: '§ Zame ni primerno, da bi se sedaj poveličeval. Prišel bom k videnjem in razodetjem od Gospoda.',
        2: 'Pred okoli štirinajstimi leti sem spoznal človeka v Kristusu (bodisi v telesu, ne morem reči; ali izven telesa, ne morem povedati; Bog ve), nekoga vzetega gor do tretjih nebes.',
        3: 'In poznal sem takšnega človeka (bodisi v telesu ali izven telesa, ne morem povedati; Bog ve),',
        4: 'kako je bil vzet gor v raj in je slišal neizgovorljive besede, ki jih človeku ni zakonito izreči.',
        5: 'S takšnim se bom ponašal. Vendar se ne bom ponašal sam s seboj, temveč s svojimi slabotnostmi.',
        6: 'Kajti kljub temu da bi se želel ponašati, ne bom bedak; kajti povedal bom resnico. Toda sedaj potrpim, da ne bi katerikoli človek mislil o meni več, kakor me vidi, da sem ali kar sliši o meni.',
        7: 'In da se ne bi zaradi obilja razodetij, prek mere povišal, mi je bil dan v meso trn, Satanov poslanec, da me udari, da ne bi bil prek mere vzvišen.',
        8: 'Za to stvar sem trikrat rotil Gospoda, da bi jo odstranil od mene.',
        9: 'In mi je rekel: »Dovolj ti je moja milost, kajti moja moč je izpopolnjena v slabotnosti.« Torej se bom z največjim veseljem raje ponašal s svojimi slabotnostmi, da bo na meni lahko počivala Kristusova moč.',
        10: 'Torej bom zaradi Kristusa užival v slabotnostih, v grajah, v potrebah, v preganjanjih, v tegobah; kajti kadar sem slaboten, tedaj sem močan.',
        11: 'Postal sem bedak v ponašanju. Prisilili ste me, kajti od vas bi moral biti priporočen. Kajti v ničemer ne zaostajam za vašimi najvodilnejšimi apostoli, čeprav nisem nič.',
        12: 'Resnično, znamenja apostola so bila med vami storjena v vsej potrpežljivosti, z znamenji in čudeži ter mogočnimi dejanji.',
        13: 'Kajti kaj je to, v čemer ste bili slabši do drugih cerkvá, razen tega, da vam jaz nisem bil v breme? Odpustite mi to krivico.',
        14: 'Glejte, tretjič sem pripravljen priti k vam, in vam ne bom v breme, kajti ne iščem vašega, temveč vas. Kajti ne bi smeli biti otroci obvezani varčevati za starše, temveč starši za otroke.',
        15: 'In zelo rad se hočem razdati in biti razdan za vas; četudi vas obilneje ljubim, sem manj ljubljen.',
        16: 'Toda naj bo tako, nisem vas bremenil; kljub temu sem vas, ker sem prebrisan, ujel z zvijačo.',
        17: 'Ali sem vas izkoristil po kom od teh, ki sem jih poslal k vam?',
        18: 'Naprosil sem Tita in z njim sem poslal brata. Ali vas je izkoristil Tit? Ali nisva hodila v istem duhu? Ali nisva hodila po istih stopinjah?',
        19: 'Ponovno, ali mislite, da se vam opravičujemo? Govorimo pred Bogom v Kristusu. Toda, srčno ljubljeni, vse stvari počenjamo v vaše izgrajevanje.',
        20: 'Kajti bojim se, da ko pridem, vas ne bom našel takšnih, kakor vas želim in da me boste vi našli takšnega, kakor si ne želite; da ne bi bilo razpravljanj, zavisti, jeze, prepirov, obrekovanj, šepetanj, napihovanj, uporov.',
        21: 'In da me ne bi, ko ponovno pridem, moj Bog med vami ponižal in da bom objokoval mnoge, ki so že grešili in se niso pokesali od nečistosti in prešuštvovanja in pohotnosti, ki so jih zagrešili.',
    },
    13: {
        1: 'To je tretjič, [da] prihajam k vam. Po ustih dveh ali treh prič bo ugotovljena vsaka beseda.',
        2: 'Povedal sem vam že nekoč in vam drugič napovedujem, kakor če bi bil prisoten; in sedaj odsoten pišem tem, ki so poprej grešili in vsem drugim, da če ponovno pridem, ne bom prizanašal.',
        3: 'Ker iščete dokaz, da Kristus govori v meni, ki posebej do vas ni slaboten, temveč je v vas mogočen.',
        4: 'Kajti čeprav je bil križan zaradi slabosti, vendarle živi z Božjo močjo. Kajti tudi mi smo šibki v njem, toda z Božjo močjo bomo živeli z njim za vas.',
        5: 'Izprašajte se, ali ste v veri. Preizkusite se. Ali se ne poznate, da je Jezus Kristus v vas, razen če ste zavrženi?',
        6: 'Toda zaupam, da boste spoznali, da mi nismo zavrženi.',
        7: 'Sedaj molim k Bogu, da ne storite nobenega zla; ne da bi se mi izkazali potrjene, temveč da bi vi storili to, kar je pošteno, čeprav smo mi kakor zavrženi.',
        8: 'Kajti ničesar ne moremo storiti proti resnici, temveč za resnico.',
        9: 'Kajti veseli smo, ko smo mi slabotni, vi pa močni; in to tudi želimo, celó vašo popolnost.',
        10: 'Zatorej pišem te stvari v odsotnosti, da ne bi navzoč uporabil ostrine, glede na oblast, ki mi jo je Gospod dal za izgrajevanje in ne za uničenje.',
        11: 'Končno, bratje, zbogom. Bodite popolni, bodite dobro potolaženi, bodite enega mišljenja, živite v miru; in z vami bo Bog ljubezni in miru.',
        12: 'Pozdravite drug drugega s svetim poljubom.',
        13: 'Pozdravljajo vas vsi sveti.',
        14: 'Milost Gospoda Jezusa Kristusa in Božja ljubezen in soudeležba Svetega Duha bodi z vami vsemi. Amen. [Druga poslanica Korinčanom je bila napisana iz Filipov, mesta v Makedoniji, po Titu in Luku.]',
    },
}
